import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const LOGIN_TYPES = ['웹', '메신저', '모바일'];

function textOf(value: unknown): string | null {
  if (typeof value === 'string' && value !== '') {
    return value;
  }
  return null;
}

function integerOf(value: unknown, name: string): number | null {
  const text = textOf(value);
  if (text === null) {
    return null;
  }
  const num = Number(text);
  if (!Number.isInteger(num)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값은 정수여야 합니다.');
  }
  return num;
}

function dateOf(value: unknown, name: string): string | null {
  const text = textOf(value);
  if (text === null) {
    return null;
  }
  if (!DATE_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 형식은 YYYY-MM-DD여야 합니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnCor00201Controller {
  @Get('/access-logs/personal-info-view-statistics')
  async getPersonalInfoViewStatistics(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const q = checks.queryOf(req.query);

    const startDate = dateOf(q['startDate'], '조회 시작일');
    const endDate = dateOf(q['endDate'], '조회 종료일');
    const employeeId = integerOf(q['employeeId'], '열람자');
    const targetInfoType = textOf(q['targetInfoType']);
    const loginType = textOf(q['loginType']);
    if (loginType !== null && !LOGIN_TYPES.includes(loginType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '로그인 구분이 올바르지 않습니다.');
    }
    const pageNo = integerOf(q['page'], '페이지');
    const sizeNo = integerOf(q['size'], '크기');
    const page = pageNo === null ? 0 : pageNo;
    const size = sizeNo === null ? DEFAULT_SIZE : sizeNo;
    if (page < 0 || size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 또는 크기 값이 올바르지 않습니다.');
    }

    return transaction(async (db) => {
      if (startDate !== null && endDate !== null) {
        const rangeRows = await db.query(
          'SELECT (CAST(:endDate AS date) < CAST(:startDate AS date)) AS "invalid"',
          { startDate, endDate },
        );
        if (rangeRows[0] && rangeRows[0].invalid === true) {
          throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 종료일이 시작일보다 앞설 수 없습니다.');
        }
      }

      const where =
        "WHERE event_type = '개인정보열람' " +
        'AND (CAST(:startDate AS date) IS NULL OR accessed_at >= CAST(:startDate AS date)) ' +
        'AND (CAST(:endDate AS date) IS NULL OR accessed_at < CAST(:endDate AS date) + 1) ' +
        'AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)) ' +
        'AND (CAST(:targetInfoType AS varchar) IS NULL OR target_info_type = CAST(:targetInfoType AS varchar)) ' +
        'AND (CAST(:loginType AS varchar) IS NULL OR login_type = CAST(:loginType AS varchar)) ';
      const filterParams = { startDate, endDate, employeeId, targetInfoType, loginType };

      const totalRows = await db.query(
        'SELECT CAST(COUNT(*) AS integer) AS "total" FROM (' +
          'SELECT 1 FROM access_log ' +
          where +
          'GROUP BY employee_id, target_info_type, login_type) t',
        filterParams,
      );
      const total = totalRows[0] ? Number(totalRows[0].total) : 0;

      const items = await db.query(
        'SELECT employee_id AS "employeeId", ' +
          'target_info_type AS "targetInfoType", ' +
          'login_type AS "loginType", ' +
          'CAST(COUNT(*) AS integer) AS "viewCount" ' +
          'FROM access_log ' +
          where +
          'GROUP BY employee_id, target_info_type, login_type ' +
          'ORDER BY employee_id, target_info_type, login_type ' +
          'LIMIT :size OFFSET :offset',
        { ...filterParams, size, offset: page * size },
      );

      return { items, page, size, total };
    });
  }
}

