import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Tiles,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const PAGE_SIZE = 20;

const EMPTY_FILTER = {
  startDate: '',
  endDate: '',
  employeeId: '' as number | string,
  targetInfoType: '',
  loginType: '',
};

export default function FnCor00201Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState({ ...EMPTY_FILTER });
  const [applied, setApplied] = useState({ ...EMPTY_FILTER });
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/access-logs/personal-info-view-statistics', role, undefined, {
        ...applied,
        page,
        size: PAGE_SIZE,
      }),
    [applied, page, role],
  );

  function search() {
    if (draft.startDate && draft.endDate && draft.endDate < draft.startDate) {
      setFormError('조회 종료일이 시작일보다 앞설 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ ...draft });
  }

  function reset() {
    setFormError('');
    setDraft({ ...EMPTY_FILTER });
    setApplied({ ...EMPTY_FILTER });
    setPage(0);
  }

  const rows: Row[] = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageViewCount = rows.reduce((sum, row) => sum + Number(row.viewCount || 0), 0);

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>통계 항목</h2>
        <Tiles items={[['조회된 항목 수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>현재 쪽 열람 건수</h2>
        <Tiles items={[['열람 건수 합계', <Num value={pageViewCount} />]]} />
      </section>
      <section className="box span-12">
        <h2>열람 이력 통계</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={draft.startDate} onChange={(v) => setDraft({ ...draft, startDate: v })} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={draft.endDate} onChange={(v) => setDraft({ ...draft, endDate: v })} />
          </Field>
          <Field label="열람자">
            <LookupSelect
              table="employee"
              role={role}
              value={draft.employeeId}
              onChange={(v) => setDraft({ ...draft, employeeId: v })}
              placeholder="전체"
            />
          </Field>
          <Field label="열람 대상 정보 유형">
            <TextInput
              value={draft.targetInfoType}
              onChange={(v) => setDraft({ ...draft, targetInfoType: v })}
            />
          </Field>
          <Field label="로그인 구분">
            <Select
              value={draft.loginType}
              onChange={(v) => setDraft({ ...draft, loginType: v })}
              options={[
                ['웹', '웹'],
                ['메신저', '메신저'],
                ['모바일', '모바일'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={[
            {
              key: 'employeeId',
              label: '임직원 ID',
              render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
            },
            { key: 'targetInfoType', label: '열람 대상 정보 유형' },
            { key: 'loginType', label: '로그인 구분' },
            { key: 'viewCount', label: '열람 건수', render: (row) => <Num value={row.viewCount} /> },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '통계 결과가 없습니다.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
    </div>
  );
}
